import { Menu, Dropdown, Avatar, Button, Drawer } from "antd";
import { UserOutlined, MenuOutlined } from "@ant-design/icons";
import { Link } from "react-router-dom";
import React,{useState} from "react";
export default function NavBar() {
  const [visible, setVisible] = useState(false);

  const profileMenu = (
    <Menu>
      <Menu.Item key="0">
        <a href="#!">Profile</a>
      </Menu.Item>
      <Menu.Item key="1">
        <a href="#!">Settings</a>
      </Menu.Item>
      <Menu.Divider />
      <Menu.Item key="3">
      <Link to="/login">Logout</Link>
      </Menu.Item>
    </Menu>

  );

  return (
    <div
      style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        borderBottom: "2px solid black", // 검정색 구분선 추가
        padding: "12px 0", // 메뉴바의 상하 패딩을 추가하여 크기를 늘림
      }}
    >
      <a
        href="#!"
        style={{
          padding: "0 16px",
          fontSize: "20px",
          fontWeight: "bold",
          color: "#1890ff",
        }}
      >
        Logo
      </a>
      <div>
        <Button
          icon={<MenuOutlined />}
          onClick={() => setVisible(true)}
          style={{ marginRight: "16px", border: "none" }}
        />
        <Dropdown overlay={profileMenu} trigger={["hover"]}>
          <Avatar icon={<UserOutlined />} />
        </Dropdown>
      </div>
      <Drawer
        title="Menu"
        placement="right"
        closable={false}
        onClose={() => setVisible(false)}
        visible={visible}
        bodyStyle={{ padding: 0 }}
        width="80%"
      >
        <Menu mode="inline">
          <Menu.Item key="home">
            <a href="#!">
            <Link to="/main">Home</Link>
            </a>
          </Menu.Item>
          <Menu.SubMenu key="carmanage" title="차량관리">
            <Menu.Item key="5">
              <a href="#!">본인차량</a>
            </Menu.Item>
            <Menu.Item key="6">
              <a href="#!">손님차량</a>
            </Menu.Item>
          </Menu.SubMenu>
          <Menu.SubMenu key="commuity" title="커뮤니티">
            <Menu.Item key="7">
              <a href="#!">공지사항</a>
            </Menu.Item>
            <Menu.Item key="8">
              <a href="#!">투표</a>
            </Menu.Item>
            <Menu.Item key="9">
              <Link to="/request">민원</Link>
            </Menu.Item>
          </Menu.SubMenu>
          <Menu.SubMenu key="facility" title="편의기능">
            <Menu.Item key="10">
              <a href="#!">최신뉴스</a>
            </Menu.Item>
            <Menu.Item key="11">
              <a href="#!">재난문자</a>
            </Menu.Item>
            <Menu.Item key="12">
              <a href="#!">주변 대중교통 정보</a>
            </Menu.Item>
            <Menu.Item key="13">
              <a href="#!">주변병의원/약국정보</a>
            </Menu.Item>
          </Menu.SubMenu>
        </Menu>
      </Drawer>
    </div>
  );
}
