import "./styles.css";
import React, { useState, useEffect } from "react";
import { Input, Typography, Button, Row, Col, Space, Checkbox } from "antd";
import { EyeInvisibleOutlined, EyeTwoTone } from "@ant-design/icons";
import Swal from "sweetalert2";
import { Link } from "react-router-dom";
import { useNavigate } from "react-router-dom";
const { Title } = Typography;

export default function App() {
  const [dong, setDong] = useState("");
  const [ho, setHo] = useState("");
  const [password, setPassword] = useState("");
  const [adminMode, setAdminMode] = useState(false);
  const navi = useNavigate();
  const goMain = () => {
    navi("/main");
  };
  const handleDongChange = (e) => {
    const { value } = e.target;
    if (/^[0-9]*$/.test(value)) {
      setDong(value);
    } else {
      Swal.fire(
        "Oops...",
        "'동' 입력이 잘못되었습니다. 입력값은 숫자여야 합니다.",
        "error"
      );
    }
    if (/(--|;|'|"|=|OR|AND)/i.test(value)) {
      Swal.fire(
        "Security Alert...",
        "SQL 인젝션 공격을 시도하는 입력이 감지되었습니다.",
        "error"
      );
    }
  };

  const handleHoChange = (e) => {
    const { value } = e.target;
    if (/^[0-9]*$/.test(value)) {
      setHo(value);
    } else {
      Swal.fire(
        "Oops...",
        "'호'수 입력이 잘못되었습니다. 입력값은 숫자여야 합니다.",
        "error"
      );
    }
    if (/(--|;|'|"|=|OR|AND)/i.test(value)) {
      Swal.fire(
        "Security Alert...",
        "SQL 인젝션 공격을 시도하는 입력이 감지되었습니다.",
        "error"
      );
    }
  };

  const handlePasswordChange = (e) => {
    setPassword(e.target.value);
  };

  const handleSubmit = async () => {
    if (!dong || !ho || !password) {
      Swal.fire("Oops...", "모든 칸을 입력해 주세요!", "warning");
      return;
    }

    // Save the login info to Local Storage
    localStorage.setItem("dong", dong);
    localStorage.setItem("ho", ho);
    localStorage.setItem("password", password);

    try {
      const response = await fetch("http://118.67.130.191:3000/user/signin", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          dong: dong,
          ho: ho,
          pw: password,
        }),
      });

      const data = await response.json();
      if (data.status === 200) {
        goMain();
      } else if (data.status === 401 && data.message === "비밀번호 불일치") {
        Swal.fire("Message", data.message, "error");
      } else if (data.status === 401 && data.message === "등록되지 않은 사용자") {
        Swal.fire("Message", data.message, "error");
      } else if (
        data.status === 400 &&
        data.message === "필수 항목 입력 필요"
      ) {
        Swal.fire("Message", data.message, "warning");
      } else {
        // 기본적인 오류 메시지 대신에 서버로부터 받은 메시지를 출력합니다.
        Swal.fire(
          "Oops...",
          data.message || "서버로부터 메시지를 받지 못했습니다.",
          "error"
        );
      }
    } catch (error) {
      Swal.fire("Error", "서버와의 통신 중 오류가 발생했습니다.", "warning");
    }
  };

  useEffect(() => {
    if (ho === "0000") {
      setAdminMode(true);
    } else {
      setAdminMode(false);
    }
  }, [ho]);

  return (
    <div
      className="App"
      style={{ display: "flex", flexDirection: "column", alignItems: "center" }}
    >
      {/* 제목 로그인 */}
      <Title level={2} style={{ marginTop: "105px" }}>
        로그인
      </Title>
      {/* 동 입력 영역 */}
      <Input
        style={{ width: "375px", height: "50px", marginTop: "16px" }}
        placeholder="동을 입력하세요."
        value={dong}
        onChange={handleDongChange}
      />
      {/* 호 입력 영역 */}
      <Input
        style={{ width: "375px", height: "50px", marginTop: "16px" }}
        placeholder="호를 입력하세요."
        value={ho}
        onChange={handleHoChange}
      />
      {/* 관리자 체크 영역 */}
      {adminMode && (
        <Checkbox style={{ marginTop: "16px" }} checked={adminMode} disabled>
          관리자체크
        </Checkbox>
      )}
      {/* 비밀번호 입력 영역 */}
      <Input.Password
        style={{ width: "375px", height: "50px", marginTop: "16px" }}
        iconRender={(visible) =>
          visible ? <EyeTwoTone /> : <EyeInvisibleOutlined />
        }
        placeholder="비밀번호를 입력하세요."
        value={password}
        onChange={handlePasswordChange}
      />
      {/* 로그인 버튼 영역 */}
      <Row gutter={[10, 16]} justify="center" style={{ marginTop: "20px" }}>
        <Col>
          <Button type="primary" onClick={handleSubmit}>
            로그인
          </Button>
        </Col>
      </Row>

      {/* 회원 가입 버튼과 비밀번호 찾기 영역 */}
      <Row gutter={[16, 16]} justify="center" style={{ marginTop: "20px" }}>
        <Col>
          <Space>
            <Button type="primary" ghost>
              <Link to="/sign" style={{ textDecoration: "none" }}>
                회원가입
              </Link>
            </Button>
            <Button type="primary" ghost>
              비밀번호 찾기
            </Button>
          </Space>
        </Col>
      </Row>
    </div>
  );
}
